import{_ as t,a as o,o as r,a6 as s}from"./chunks/framework.CJDy2q7X.js";const h=JSON.parse('{"title":"Reporting — Products","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"rest-products-total-sold-quantities","title":"Total Sold Quantities","description":"Default report. Total units sold in the window vs. the previous window, plus a per-day `over_time` series for the chart line.","query":"curl -X GET \\"https://your-domain.com/api/admin/reporting/products?type=total-sold-quantities&start=2026-05-10&end=2026-06-09&channel=default\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"Authorization: Bearer <id>|<token>\\"\\n","response":"[\\n  {\\n    \\"entity\\": \\"products\\",\\n    \\"type\\": \\"total-sold-quantities\\",\\n    \\"dateRange\\": { \\"previous\\": \\"10 Apr 2026 - 10 May 2026\\", \\"current\\": \\"10 May 2026 - 09 Jun 2026\\" },\\n    \\"statistics\\": {\\n      \\"quantities\\": { \\"previous\\": 82, \\"current\\": 113, \\"progress\\": 37.8 },\\n      \\"over_time\\": {\\n        \\"previous\\": [\\n          { \\"label\\": \\"10 Apr\\", \\"total\\": 21 },\\n          { \\"label\\": \\"11 Apr\\", \\"total\\": 14 }\\n        ],\\n        \\"current\\": [\\n          { \\"label\\": \\"10 May\\", \\"total\\": 35 },\\n          { \\"label\\": \\"11 May\\", \\"total\\": 28 }\\n        ]\\n      }\\n    }\\n  }\\n]\\n"},{"id":"rest-products-total-products-added-to-wishlist","title":"Total Products Added to Wishlist","description":"Count of wishlist additions in the window vs. the previous window, plus a per-day `over_time` series.","query":"curl -X GET \\"https://your-domain.com/api/admin/reporting/products?type=total-products-added-to-wishlist&start=2026-05-10&end=2026-06-09&channel=default\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"Authorization: Bearer <id>|<token>\\"\\n","response":"[\\n  {\\n    \\"entity\\": \\"products\\",\\n    \\"type\\": \\"total-products-added-to-wishlist\\",\\n    \\"dateRange\\": { \\"previous\\": \\"10 Apr 2026 - 10 May 2026\\", \\"current\\": \\"10 May 2026 - 09 Jun 2026\\" },\\n    \\"statistics\\": {\\n      \\"wishlist\\": { \\"previous\\": 12, \\"current\\": 19, \\"progress\\": 58.33 },\\n      \\"over_time\\": {\\n        \\"previous\\": [\\n          { \\"label\\": \\"10 Apr\\", \\"total\\": 4 },\\n          { \\"label\\": \\"11 Apr\\", \\"total\\": 2 }\\n        ],\\n        \\"current\\": [\\n          { \\"label\\": \\"10 May\\", \\"total\\": 6 },\\n          { \\"label\\": \\"11 May\\", \\"total\\": 3 }\\n        ]\\n      }\\n    }\\n  }\\n]\\n"},{"id":"rest-products-top-selling-products-by-revenue","title":"Top Selling Products by Revenue","description":"Best-selling products ranked by revenue. Here `statistics` is a flat array of product rows, each carrying a nested `images` array.","query":"curl -X GET \\"https://your-domain.com/api/admin/reporting/products?type=top-selling-products-by-revenue&start=2026-05-10&end=2026-06-09&channel=default\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"Authorization: Bearer <id>|<token>\\"\\n","response":"[\\n  {\\n    \\"entity\\": \\"products\\",\\n    \\"type\\": \\"top-selling-products-by-revenue\\",\\n    \\"dateRange\\": { \\"previous\\": \\"10 Apr 2026 - 10 May 2026\\", \\"current\\": \\"10 May 2026 - 09 Jun 2026\\" },\\n    \\"statistics\\": [\\n      {\\n        \\"id\\": 2359,\\n        \\"name\\": \\"Horizon Arc 49\\\\\\" OLED Curved Gaming Monitor\\",\\n        \\"price\\": \\"4000.0000\\",\\n        \\"formatted_price\\": \\"$3,899.00\\",\\n        \\"revenue\\": \\"38990.0000\\",\\n        \\"formatted_revenue\\": \\"$38,990.00\\",\\n        \\"progress\\": 142.6,\\n        \\"images\\": [\\n          {\\n            \\"id\\": 786,\\n            \\"type\\": \\"images\\",\\n            \\"path\\": \\"product/2359/Whw0RJrR1dLPn5HHkyk7G7hiUpY6aH8BFYOE7rlc.webp\\",\\n            \\"product_id\\": 2359,\\n            \\"position\\": 1,\\n            \\"url\\": \\"https://your-domain.com/storage/product/2359/Whw0RJrR1dLPn5HHkyk7G7hiUpY6aH8BFYOE7rlc.webp\\"\\n          }\\n        ]\\n      },\\n      {\\n        \\"id\\": 1184,\\n        \\"name\\": \\"Wireless Noise-Cancelling Headphones\\",\\n        \\"price\\": null,\\n        \\"formatted_price\\": \\"$0.00\\",\\n        \\"revenue\\": \\"12840.0000\\",\\n        \\"formatted_revenue\\": \\"$12,840.00\\",\\n        \\"progress\\": -8.4,\\n        \\"images\\": []\\n      }\\n    ]\\n  }\\n]\\n"},{"id":"rest-products-top-selling-products-by-quantity","title":"Top Selling Products by Quantity","description":"Best-selling products ranked by units sold. `statistics` is a flat array; each row carries `total_qty_ordered` and a nested `images` array.","query":"curl -X GET \\"https://your-domain.com/api/admin/reporting/products?type=top-selling-products-by-quantity&start=2026-05-10&end=2026-06-09&channel=default\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"Authorization: Bearer <id>|<token>\\"\\n","response":"[\\n  {\\n    \\"entity\\": \\"products\\",\\n    \\"type\\": \\"top-selling-products-by-quantity\\",\\n    \\"dateRange\\": { \\"previous\\": \\"10 Apr 2026 - 10 May 2026\\", \\"current\\": \\"10 May 2026 - 09 Jun 2026\\" },\\n    \\"statistics\\": [\\n      {\\n        \\"id\\": 1184,\\n        \\"name\\": \\"Wireless Noise-Cancelling Headphones\\",\\n        \\"price\\": \\"199.0000\\",\\n        \\"formatted_price\\": \\"$199.00\\",\\n        \\"total_qty_ordered\\": 64,\\n        \\"progress\\": 21.5,\\n        \\"images\\": [\\n          {\\n            \\"id\\": 412,\\n            \\"type\\": \\"images\\",\\n            \\"path\\": \\"product/1184/8KpQ2mLnVxRtY7wZbN3cHaUjE9fGdSiO4lP6vTqA.webp\\",\\n            \\"product_id\\": 1184,\\n            \\"position\\": 1,\\n            \\"url\\": \\"https://your-domain.com/storage/product/1184/8KpQ2mLnVxRtY7wZbN3cHaUjE9fGdSiO4lP6vTqA.webp\\"\\n          }\\n        ]\\n      },\\n      {\\n        \\"id\\": 2359,\\n        \\"name\\": \\"Horizon Arc 49\\\\\\" OLED Curved Gaming Monitor\\",\\n        \\"price\\": \\"4000.0000\\",\\n        \\"formatted_price\\": \\"$3,899.00\\",\\n        \\"total_qty_ordered\\": 10,\\n        \\"progress\\": -3.2,\\n        \\"images\\": []\\n      }\\n    ]\\n  }\\n]\\n"},{"id":"rest-products-products-with-most-reviews","title":"Products with Most Reviews","description":"Products ranked by review count in the window. `statistics` is a flat array of `{ product_id, product_name, reviews, progress }` rows.","query":"curl -X GET \\"https://your-domain.com/api/admin/reporting/products?type=products-with-most-reviews&start=2026-05-10&end=2026-06-09&channel=default\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"Authorization: Bearer <id>|<token>\\"\\n","response":"[\\n  {\\n    \\"entity\\": \\"products\\",\\n    \\"type\\": \\"products-with-most-reviews\\",\\n    \\"dateRange\\": { \\"previous\\": \\"10 Apr 2026 - 10 May 2026\\", \\"current\\": \\"10 May 2026 - 09 Jun 2026\\" },\\n    \\"statistics\\": [\\n      {\\n        \\"product_id\\": 1184,\\n        \\"product_name\\": \\"Wireless Noise-Cancelling Headphones\\",\\n        \\"reviews\\": 18,\\n        \\"progress\\": 12.5\\n      },\\n      {\\n        \\"product_id\\": 2359,\\n        \\"product_name\\": \\"Horizon Arc 49\\\\\\" OLED Curved Gaming Monitor\\",\\n        \\"reviews\\": 7,\\n        \\"progress\\": -10.0\\n      }\\n    ]\\n  }\\n]\\n"},{"id":"rest-products-products-with-most-visits","title":"Products with Most Visits","description":"Products ranked by storefront visit count. `statistics` is a flat array of `{ visitable_id, name, visits, progress }` rows. Depends on visitor/analytics data — empty on a fresh store.","query":"curl -X GET \\"https://your-domain.com/api/admin/reporting/products?type=products-with-most-visits&start=2026-05-10&end=2026-06-09&channel=default\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"Authorization: Bearer <id>|<token>\\"\\n","response":"[\\n  {\\n    \\"entity\\": \\"products\\",\\n    \\"type\\": \\"products-with-most-visits\\",\\n    \\"dateRange\\": { \\"previous\\": \\"10 Apr 2026 - 10 May 2026\\", \\"current\\": \\"10 May 2026 - 09 Jun 2026\\" },\\n    \\"statistics\\": [\\n      {\\n        \\"visitable_id\\": 1184,\\n        \\"name\\": \\"Wireless Noise-Cancelling Headphones\\",\\n        \\"visits\\": 432,\\n        \\"progress\\": 64.2\\n      },\\n      {\\n        \\"visitable_id\\": 2359,\\n        \\"name\\": \\"Horizon Arc 49\\\\\\" OLED Curved Gaming Monitor\\",\\n        \\"visits\\": 281,\\n        \\"progress\\": 18.9\\n      }\\n    ]\\n  }\\n]\\n"},{"id":"rest-products-last-search-terms","title":"Last Search Terms","description":"Most recent storefront search terms. `statistics` is a flat array of `{ id, term, results, uses, channel_id, locale }` rows.","query":"curl -X GET \\"https://your-domain.com/api/admin/reporting/products?type=last-search-terms&start=2026-05-10&end=2026-06-09&channel=default\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"Authorization: Bearer <id>|<token>\\"\\n","response":"[\\n  {\\n    \\"entity\\": \\"products\\",\\n    \\"type\\": \\"last-search-terms\\",\\n    \\"dateRange\\": { \\"previous\\": \\"10 Apr 2026 - 10 May 2026\\", \\"current\\": \\"10 May 2026 - 09 Jun 2026\\" },\\n    \\"statistics\\": [\\n      {\\n        \\"id\\": 91,\\n        \\"term\\": \\"gaming monitor\\",\\n        \\"results\\": 14,\\n        \\"uses\\": 3,\\n        \\"channel_id\\": 1,\\n        \\"locale\\": \\"en\\"\\n      },\\n      {\\n        \\"id\\": 90,\\n        \\"term\\": \\"wireless headphones\\",\\n        \\"results\\": 22,\\n        \\"uses\\": 8,\\n        \\"channel_id\\": 1,\\n        \\"locale\\": \\"en\\"\\n      }\\n    ]\\n  }\\n]\\n"},{"id":"rest-products-top-search-terms","title":"Top Search Terms","description":"Most-used storefront search terms. `statistics` is a flat array of `{ id, term, results, uses, channel_id, locale }` rows. This report has no View Details (table) form.","query":"curl -X GET \\"https://your-domain.com/api/admin/reporting/products?type=top-search-terms&start=2026-05-10&end=2026-06-09&channel=default\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"Authorization: Bearer <id>|<token>\\"\\n","response":"[\\n  {\\n    \\"entity\\": \\"products\\",\\n    \\"type\\": \\"top-search-terms\\",\\n    \\"dateRange\\": { \\"previous\\": \\"10 Apr 2026 - 10 May 2026\\", \\"current\\": \\"10 May 2026 - 09 Jun 2026\\" },\\n    \\"statistics\\": [\\n      {\\n        \\"id\\": 90,\\n        \\"term\\": \\"wireless headphones\\",\\n        \\"results\\": 22,\\n        \\"uses\\": 8,\\n        \\"channel_id\\": 1,\\n        \\"locale\\": \\"en\\"\\n      },\\n      {\\n        \\"id\\": 91,\\n        \\"term\\": \\"gaming monitor\\",\\n        \\"results\\": 14,\\n        \\"uses\\": 3,\\n        \\"channel_id\\": 1,\\n        \\"locale\\": \\"en\\"\\n      }\\n    ]\\n  }\\n]\\n"},{"id":"rest-products-view","title":"View Details (table form)","description":"The expanded, row-by-row table behind a panel\'s \\"View Details\\" link. `statistics` is `{ columns, records }` and honors the same `type` values (except `top-search-terms`, which has no table form).","query":"curl -X GET \\"https://your-domain.com/api/admin/reporting/products/view?type=top-selling-products-by-revenue&start=2026-05-10&end=2026-06-09&channel=default\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"Authorization: Bearer <id>|<token>\\"\\n","response":"[\\n  {\\n    \\"entity\\": \\"products\\",\\n    \\"type\\": \\"top-selling-products-by-revenue\\",\\n    \\"dateRange\\": { \\"previous\\": \\"10 Apr 2026 - 10 May 2026\\", \\"current\\": \\"10 May 2026 - 09 Jun 2026\\" },\\n    \\"statistics\\": {\\n      \\"columns\\": [\\n        { \\"key\\": \\"id\\", \\"label\\": \\"ID\\" },\\n        { \\"key\\": \\"name\\", \\"label\\": \\"Name\\" },\\n        { \\"key\\": \\"formatted_price\\", \\"label\\": \\"Price\\" },\\n        { \\"key\\": \\"formatted_revenue\\", \\"label\\": \\"Total Revenue\\" }\\n      ],\\n      \\"records\\": [\\n        {\\n          \\"id\\": 2359,\\n          \\"name\\": \\"Horizon Arc 49\\\\\\" OLED Curved Gaming Monitor\\",\\n          \\"price\\": \\"4000.0000\\",\\n          \\"formatted_price\\": \\"$3,899.00\\",\\n          \\"revenue\\": \\"38990.0000\\",\\n          \\"formatted_revenue\\": \\"$38,990.00\\",\\n          \\"images\\": [\\n            {\\n              \\"id\\": 786,\\n              \\"type\\": \\"images\\",\\n              \\"path\\": \\"product/2359/Whw0RJrR1dLPn5HHkyk7G7hiUpY6aH8BFYOE7rlc.webp\\",\\n              \\"product_id\\": 2359,\\n              \\"position\\": 1,\\n              \\"url\\": \\"https://your-domain.com/storage/product/2359/Whw0RJrR1dLPn5HHkyk7G7hiUpY6aH8BFYOE7rlc.webp\\"\\n            }\\n          ]\\n        }\\n      ]\\n    }\\n  }\\n]\\n"},{"id":"rest-products-export","title":"Export (CSV)","description":"Streams the View Details table as a text/csv attachment (the \\"Export\\" button). Send Accept text/csv. Only format=csv is accepted; any other value returns 422.","query":"curl -X GET \\"https://your-domain.com/api/admin/reporting/products/export?type=top-selling-products-by-revenue&format=csv&start=2026-05-10&end=2026-06-09&channel=default\\" \\\\\\n  -H \\"Authorization: Bearer <id>|<token>\\" \\\\\\n  -H \\"Accept: text/csv\\" \\\\\\n  -o products-report.csv\\n","response":"ID,Name,Price,Total Revenue\\n2359,\\"Horizon Arc 49\\"\\" OLED Curved Gaming Monitor\\",\\"$3,899.00\\",\\"$38,990.00\\"\\n1184,\\"Wireless Noise-Cancelling Headphones\\",\\"$199.00\\",\\"$12,840.00\\"\\n"},{"id":"rest-products-export-xlsx","title":"Export (XLSX)","description":"Streams the View Details table as a text/csv attachment (the \\"Export\\" button). Send Accept text/csv. Only format=xlsx is accepted; any other value returns 422.","query":"curl -X GET \\"https://your-domain.com/api/admin/reporting/products/export?type=top-selling-products-by-revenue&format=xlsx&start=2026-05-10&end=2026-06-09&channel=default\\" \\\\\\n  -H \\"Authorization: Bearer <id>|<token>\\" \\\\\\n  -H \\"Accept: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet\\" \\\\\\n  -o products-report.xlsx\\n","response":"# Binary response: an XLSX workbook is written to disk\\n# (Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet\\n#  Content-Disposition: attachment; filename=\\"products-<type>.xlsx\\").\\n# Same columns as the CSV export, as the first sheet\'s header row plus one row per record.\\n"}]},"headers":[],"relativePath":"api/rest-api/admin/reporting/products.md","filePath":"api/rest-api/admin/reporting/products.md","lastUpdated":1787725411000}'),a={name:"api/rest-api/admin/reporting/products.md"};function n(d,e,i,c,p,l){return r(),o("div",null,e[0]||(e[0]=[s('<h1 id="reporting-—-products" tabindex="-1">Reporting — Products <a class="header-anchor" href="#reporting-—-products" aria-label="Permalink to &quot;Reporting — Products&quot;">​</a></h1><p>Returns the aggregate statistics that power the Bagisto admin <strong>Reporting → Products</strong> screen — sold quantities, wishlist additions, top sellers, review counts, visit counts and search-term analytics.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stats endpoint</strong></td><td><code>GET /api/admin/reporting/products</code></td></tr><tr><td><strong>View Details endpoint</strong></td><td><code>GET /api/admin/reporting/products/view</code></td></tr><tr><td><strong>Export endpoint</strong></td><td><code>GET /api/admin/reporting/products/export</code></td></tr><tr><td><strong>Returns</strong></td><td>A JSON <strong>array</strong> with a single element: <code>[ { entity, type, dateRange, statistics } ]</code> (<code>entity</code> is always <code>&quot;products&quot;</code>)</td></tr></tbody></table><h2 id="understanding-type-—-the-products-report-is-eight-separate-calls" tabindex="-1">Understanding <code>type</code> — the Products report is <strong>eight</strong> separate calls <a class="header-anchor" href="#understanding-type-—-the-products-report-is-eight-separate-calls" aria-label="Permalink to &quot;Understanding `type` — the Products report is **eight** separate calls&quot;">​</a></h2><p>This is the most important thing to understand about this API.</p><p>The Products reporting screen is <strong>not one response</strong>. Each panel is a separate request selected with the <code>?type=</code> query parameter. A single call returns <strong>one report</strong>, and the <code>statistics</code> payload <strong>changes shape per <code>type</code></strong> — sometimes an object (the chart reports), sometimes a flat array (the ranked-list reports) — so always branch on <code>type</code> when consuming it.</p><p><code>total-sold-quantities</code> is the default — if you omit <code>?type=</code>, you get the sold-quantities chart.</p><h2 id="query-parameters" tabindex="-1">Query parameters <a class="header-anchor" href="#query-parameters" aria-label="Permalink to &quot;Query parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Param</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>type</code></td><td>enum</td><td>No</td><td>One of the eight values listed below. Defaults to <code>total-sold-quantities</code>. An unknown value returns <strong>400</strong> (<code>invalid-type</code>).</td></tr><tr><td><code>start</code></td><td>date (YYYY-MM-DD)</td><td>No</td><td>Lower bound of the reporting window. Defaults to <strong>30 days ago</strong>.</td></tr><tr><td><code>end</code></td><td>date (YYYY-MM-DD)</td><td>No</td><td>Upper bound. Defaults to <strong>today</strong>.</td></tr><tr><td><code>channel</code></td><td>string</td><td>No</td><td>Channel <strong>code</strong> to scope the figures to a single channel. Defaults to all channels.</td></tr></tbody></table><p><code>start</code> / <code>end</code> drive both the figures and the <code>previous</code> baseline used for each <code>progress</code> percentage — the previous period is the same-length window immediately before <code>start</code>.</p><h2 id="response-envelope" tabindex="-1">Response envelope <a class="header-anchor" href="#response-envelope" aria-label="Permalink to &quot;Response envelope&quot;">​</a></h2><p>The endpoint always returns a <strong>single-element array</strong>: <code>[ { entity, type, dateRange, statistics } ]</code>.</p><ul><li><code>entity</code> — always <code>&quot;products&quot;</code>.</li><li><code>type</code> — echoes back the requested report.</li><li><code>dateRange</code> — an <strong>object</strong> <code>{ previous, current }</code> with a human-readable label for each window (e.g. <code>{ &quot;previous&quot;: &quot;10 Apr 2026 - 10 May 2026&quot;, &quot;current&quot;: &quot;10 May 2026 - 09 Jun 2026&quot; }</code>).</li><li><code>statistics</code> — an object or array whose shape depends on <code>type</code> (documented below).</li></ul><h2 id="response-shapes-by-type" tabindex="-1">Response shapes by <code>type</code> <a class="header-anchor" href="#response-shapes-by-type" aria-label="Permalink to &quot;Response shapes by `type`&quot;">​</a></h2><p>Figures with a <code>previous</code> / <code>current</code> / <code>progress</code> shape are period comparisons: <code>current</code> is the chosen window, <code>previous</code> is the preceding window of equal length, and <code>progress</code> is the percentage change (can be negative).</p><table tabindex="0"><thead><tr><th><code>type</code></th><th><code>statistics</code> is</th><th>Shape</th></tr></thead><tbody><tr><td><code>total-sold-quantities</code></td><td>object</td><td><code>{ quantities: { previous, current, progress }, over_time: { previous: [{label,total}], current: [{label,total}] } }</code></td></tr><tr><td><code>total-products-added-to-wishlist</code></td><td>object</td><td><code>{ wishlist: { previous, current, progress }, over_time: { previous: [{label,total}], current: [{label,total}] } }</code></td></tr><tr><td><code>top-selling-products-by-revenue</code></td><td>array</td><td>rows of <code>{ id, name, price, formatted_price, revenue, formatted_revenue, progress, images: [{id,type,path,product_id,position,url}] }</code></td></tr><tr><td><code>top-selling-products-by-quantity</code></td><td>array</td><td>rows of <code>{ id, name, price, formatted_price, total_qty_ordered, progress, images: [{id,type,path,product_id,position,url}] }</code></td></tr><tr><td><code>products-with-most-reviews</code></td><td>array</td><td>rows of <code>{ product_id, product_name, reviews, progress }</code></td></tr><tr><td><code>products-with-most-visits</code></td><td>array</td><td>rows of <code>{ visitable_id, name, visits, progress }</code></td></tr><tr><td><code>last-search-terms</code></td><td>array</td><td>rows of <code>{ id, term, results, uses, channel_id, locale }</code></td></tr><tr><td><code>top-search-terms</code></td><td>array</td><td>rows of <code>{ id, term, results, uses, channel_id, locale }</code></td></tr></tbody></table><h3 id="total-sold-quantities" tabindex="-1"><code>total-sold-quantities</code> <a class="header-anchor" href="#total-sold-quantities" aria-label="Permalink to &quot;`total-sold-quantities`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Shape</th><th>Meaning</th></tr></thead><tbody><tr><td><code>quantities</code></td><td><code>{ previous, current, progress }</code></td><td>Total units sold in the window vs. the previous window.</td></tr><tr><td><code>over_time</code></td><td><code>{ previous: [{label,total}], current: [{label,total}] }</code></td><td>Two per-day series (previous and current windows) for the chart line; <code>total</code> is units sold per bucket.</td></tr></tbody></table><h3 id="total-products-added-to-wishlist" tabindex="-1"><code>total-products-added-to-wishlist</code> <a class="header-anchor" href="#total-products-added-to-wishlist" aria-label="Permalink to &quot;`total-products-added-to-wishlist`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Shape</th><th>Meaning</th></tr></thead><tbody><tr><td><code>wishlist</code></td><td><code>{ previous, current, progress }</code></td><td>Wishlist additions in the window vs. the previous window.</td></tr><tr><td><code>over_time</code></td><td><code>{ previous: [{label,total}], current: [{label,total}] }</code></td><td>Two per-day series for the chart line; <code>total</code> is additions per bucket.</td></tr></tbody></table><h3 id="top-selling-products-by-revenue" tabindex="-1"><code>top-selling-products-by-revenue</code> <a class="header-anchor" href="#top-selling-products-by-revenue" aria-label="Permalink to &quot;`top-selling-products-by-revenue`&quot;">​</a></h3><p><code>statistics</code> is an <strong>array</strong> of product rows. Each row: <code>id</code>, <code>name</code>, <code>price</code> (may be <code>null</code>), <code>formatted_price</code>, <code>revenue</code>, <code>formatted_revenue</code>, <code>progress</code>, and <code>images</code> (array of <code>{ id, type, path, product_id, position, url }</code> — empty when the product has no image).</p><h3 id="top-selling-products-by-quantity" tabindex="-1"><code>top-selling-products-by-quantity</code> <a class="header-anchor" href="#top-selling-products-by-quantity" aria-label="Permalink to &quot;`top-selling-products-by-quantity`&quot;">​</a></h3><p><code>statistics</code> is an <strong>array</strong> of product rows. Each row: <code>id</code>, <code>name</code>, <code>price</code>, <code>formatted_price</code>, <code>total_qty_ordered</code>, <code>progress</code>, and <code>images</code> (array of <code>{ id, type, path, product_id, position, url }</code>).</p><h3 id="products-with-most-reviews" tabindex="-1"><code>products-with-most-reviews</code> <a class="header-anchor" href="#products-with-most-reviews" aria-label="Permalink to &quot;`products-with-most-reviews`&quot;">​</a></h3><p><code>statistics</code> is an <strong>array</strong>. Each row: <code>product_id</code>, <code>product_name</code>, <code>reviews</code> (count in the window), <code>progress</code>.</p><h3 id="products-with-most-visits" tabindex="-1"><code>products-with-most-visits</code> <a class="header-anchor" href="#products-with-most-visits" aria-label="Permalink to &quot;`products-with-most-visits`&quot;">​</a></h3><p><code>statistics</code> is an <strong>array</strong>. Each row: <code>visitable_id</code>, <code>name</code>, <code>visits</code>, <code>progress</code>. Visit figures depend on the Bagisto visitor/analytics tables being populated; on a fresh store this report is <strong>empty</strong>.</p><h3 id="last-search-terms" tabindex="-1"><code>last-search-terms</code> <a class="header-anchor" href="#last-search-terms" aria-label="Permalink to &quot;`last-search-terms`&quot;">​</a></h3><p><code>statistics</code> is an <strong>array</strong> of the most recent storefront searches. Each row: <code>id</code>, <code>term</code>, <code>results</code> (matches returned), <code>uses</code> (times searched), <code>channel_id</code>, <code>locale</code>.</p><h3 id="top-search-terms" tabindex="-1"><code>top-search-terms</code> <a class="header-anchor" href="#top-search-terms" aria-label="Permalink to &quot;`top-search-terms`&quot;">​</a></h3><p><code>statistics</code> is an <strong>array</strong> of the most-used storefront searches — same row shape as <code>last-search-terms</code> (<code>id</code>, <code>term</code>, <code>results</code>, <code>uses</code>, <code>channel_id</code>, <code>locale</code>), ranked by <code>uses</code>. <strong>This report has no View Details (table) form</strong> — it is stats-only.</p><h2 id="view-details-table-form" tabindex="-1">View Details (table form) <a class="header-anchor" href="#view-details-table-form" aria-label="Permalink to &quot;View Details (table form)&quot;">​</a></h2><p><code>GET /api/admin/reporting/products/view</code> returns the same reports in a detailed table form — the full list behind a panel&#39;s <strong>View Details</strong> link. It honors the <strong>same <code>type</code> values</strong> as the stats endpoint (with the exception of <code>top-search-terms</code>, which has no table form). Here <code>statistics</code> is always an object with two keys:</p><ul><li><code>columns</code> — an ordered list of <code>{ key, label }</code> describing each table column.</li><li><code>records</code> — the row data; each record is keyed by the column <code>key</code> values (records may carry extra fields beyond the displayed columns, e.g. the raw <code>revenue</code> / <code>images</code> alongside the formatted display values).</li></ul><p>This is the expanded, row-by-row view; the summary stats endpoint returns the rolled-up headline figures instead.</p><h2 id="export-csv" tabindex="-1">Export (CSV) <a class="header-anchor" href="#export-csv" aria-label="Permalink to &quot;Export (CSV)&quot;">​</a></h2><p><code>GET /api/admin/reporting/products/export</code> streams the same detailed table as a csv, xls or xlsx attachment (the <strong>Export</strong> button). The header row is built from the column labels, followed by one line per record. Send the <code>Accept</code> header matching the requested format and save the response to a file.</p><p><code>?format=</code> accepts <code>csv</code> (the default), <code>xls</code> and <code>xlsx</code> — any other value returns HTTP <strong>422</strong>. Send an <code>Accept</code> header matching the format: <code>text/csv</code>, <code>application/vnd.ms-excel</code> or <code>application/vnd.openxmlformats-officedocument.spreadsheetml.sheet</code>.</p><p>Both <strong>View Details</strong> and <strong>Export</strong> require only authentication; reporting has no permission gate.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Condition</th><th>HTTP</th><th>Body</th></tr></thead><tbody><tr><td>Missing / invalid Bearer token</td><td><code>401</code></td><td><code>{ &quot;message&quot;: &quot;Unauthenticated.&quot;, &quot;error&quot;: &quot;unauthenticated&quot; }</code></td></tr><tr><td>Unknown <code>type</code> value</td><td><code>400</code></td><td><code>{ ... &quot;Invalid reporting stat type.&quot; }</code></td></tr><tr><td><code>format</code> other than <code>csv</code> on Export</td><td><code>422</code></td><td><code>{ ... unsupported export format }</code></td></tr></tbody></table><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/api/graphql-api/admin/reporting/products.html">Reporting — Products (GraphQL)</a> — same data over the <code>statsAdminReportingProducts</code> query.</li><li><a href="/api/rest-api/admin/dashboard/stats.html">Dashboard Statistics</a> — the at-a-glance dashboard figures.</li></ul>',44)]))}const m=t(a,[["render",n]]);export{h as __pageData,m as default};
